import React from 'react'

function Productcard({ productName, price }) {
  return (
    
         <div style={{ border: "2px solid black", padding: "15px", width: "250px" }}>
      <h2>{productName}</h2>
      <p>Price: ₹{price}</p>
    </div>
  );
  
  
}

export default Productcard
